Lemma KL2_brk_grow2 : forall L pbrk h b l, KL2 L pbrk h -> ld_brk L = BPLive -> ld_brkreg L = Some (b, l) ->
  let br := vm_brk h in
  let req := b + l + PGSZ in
  pbrk = b + l /\ bv_unsigned br = b + l /\ req = bv_unsigned br + PGSZ /\ bv_unsigned br mod PGSZ = 0 /\ 0 < bv_unsigned br
